#include <bits/stdc++.h>

using namespace std;

template<class T, class U>
void ckmin(T &a, U b)
{
	if (a > b) a = b;
}
template<class T, class U>
void ckmax(T &a, U b)
{
	if (a < b) a = b;
}

#define MP make_pair
#define PB push_back
#define LB lower_bound
#define UB upper_bound
#define fi first
#define se second
#define FOR(i, a, b) for (auto i = (a); i < (b); i++)
#define FORD(i, a, b) for (auto i = (a) - 1; i >= (b); i--)
#define SZ(x) ((int) ((x).size()))
#define ALL(x) (x).begin(), (x).end()
#define INF 1000000007
#define LLINF 2696969696969696969ll

typedef long long ll;
typedef long double ld;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef vector<int> vi;
typedef vector<ll> vl;
typedef vector<pii> vpi;
typedef vector<pll> vpl;
typedef vector<vl> mat;

ll N, K;
vi num;
mat trans;
mat base[60][30], pref[60][30], suf[60][30];
ll total_count;

mat multiply_matrices(const mat &a, const mat &b)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			res[i][j] = 0;
			FOR(k, 0, K + 1)
			{
				res[i][j] += a[i][k] * b[k][j];
				res[i][j] %= INF;
			}
		}
	}
	return res;
}
mat shift_matrix_by(const mat &a, int shift)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			if (a[i][j] == 0) continue;
			if (i == j) res[i][j] = a[i][j];
			else res[i][(j + shift) % K] = a[i][j];
		}
	}
	return res;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cin >> N >> K;
	while (N)
	{
		num.PB(N % K);
		N /= K;
	}
	FOR(i, 0, K)
	{
		base[0][i].resize(K + 1);
		FOR(j, 0, K + 1) base[0][i][j].resize(K + 1);
		FOR(j, 0, K + 1)
		{
			base[0][i][j][j] = 1;
		}
		FOR(j, 0, K + 1)
		{
			base[0][i][j][i] = 1;
		}
	}
	FOR(i, 1, SZ(num))
	{
		pref[i - 1][0] = base[i - 1][0];
		FOR(j, 1, K)
		{
			pref[i - 1][j] = multiply_matrices(pref[i - 1][j - 1], base[i - 1][j]);
		}
		suf[i - 1][K - 1] = base[i - 1][K - 1];
		FORD(j, K - 1, 0)
		{
			suf[i - 1][j] = multiply_matrices(base[i - 1][j], suf[i - 1][j + 1]);
		}
		base[i][0] = pref[i - 1][K - 1];
		FOR(j, 1, K)
		{
			base[i][j] = multiply_matrices(suf[i - 1][j], pref[i - 1][j - 1]);
		}
	}
	trans.resize(K + 1);
	FOR(i, 0, K + 1) trans[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			trans[i][j] = 0;
		}
		trans[i][i] = 1;
	}
	int sum = 0;
	FORD(i, SZ(num), 0)
	{
		int x = num[i];
		FOR(j, 0, x)
		{
			trans = multiply_matrices(trans, base[i][total_count]);
			total_count++; if (total_count >= K) total_count -= K;
		}
	}
	ll final_ans = 1;
	FOR(i, 0, K)
	{
		final_ans += trans[K][i];
		final_ans %= INF;
	}
	cout << final_ans << '\n';
	return 0;
}
